{
  "name": "rLINE电动移液器",
  "name_en": "rLINE electronic pipette",
  "manufacturer": "",
  "description": "用于控制 rLINE 电动移液器进行吸液、分液、吹出、退吸头、回零和复位，并读取位置与级别反馈，适合实验室自动化液体处理流程。",
  "description_en": "Controls an rLINE electronic pipette for aspiration, dispensing, blowout, tip ejection, homing, and reset, while reading position and level feedback for automated laboratory liquid-handling workflows.",
  "actions": [
    {
      "action_name": "auto-parseError",
      "description": "解析设备返回的错误信息。",
      "description_en": "Parse error information returned by the device."
    },
    {
      "action_name": "auto-waitAck",
      "description": "等待设备确认应答。",
      "description_en": "Wait for an acknowledgement from the device."
    },
    {
      "action_name": "auto-readFeedback",
      "description": "读取设备反馈数据。",
      "description_en": "Read feedback data from the device."
    },
    {
      "action_name": "auto-check_connection",
      "description": "检查移液器连接状态。",
      "description_en": "Check the connection status of the pipette."
    },
    {
      "action_name": "auto-sendCmd",
      "description": "向移液器发送底层控制命令。",
      "description_en": "Send a low-level control command to the pipette."
    },
    {
      "action_name": "auto-tellPosition",
      "description": "读取移液器当前位置。",
      "description_en": "Read the current position of the pipette."
    },
    {
      "action_name": "auto-tellLevel",
      "description": "读取移液器当前级别反馈。",
      "description_en": "Read the current level feedback of the pipette."
    },
    {
      "action_name": "auto-initiate_rline",
      "description": "初始化 rLINE 移液器。",
      "description_en": "Initialize the rLINE pipette."
    },
    {
      "action_name": "auto-aspirate",
      "description": "按指定体积执行吸液。",
      "description_en": "Aspirate a specified volume."
    },
    {
      "action_name": "auto-dispense",
      "description": "按指定体积分液。",
      "description_en": "Dispense a specified volume."
    },
    {
      "action_name": "auto-clear_and_reset",
      "description": "清空并复位移液器状态。",
      "description_en": "Clear and reset the pipette state."
    },
    {
      "action_name": "auto-reset",
      "description": "复位移液器。",
      "description_en": "Reset the pipette."
    },
    {
      "action_name": "auto-blowout",
      "description": "执行吹出以排尽残余液体。",
      "description_en": "Perform a blowout to expel residual liquid."
    },
    {
      "action_name": "auto-eject",
      "description": "退吸头。",
      "description_en": "Eject the pipette tip."
    },
    {
      "action_name": "auto-eject_and_home",
      "description": "退吸头并回到原位。",
      "description_en": "Eject the tip and return to the home position."
    },
    {
      "action_name": "auto-disconnect_pipette",
      "description": "断开与移液器的连接。",
      "description_en": "Disconnect from the pipette."
    }
  ],
  "tag_hints": [
    "electronic pipette",
    "liquid handling",
    "aspiration and dispense",
    "tip ejection",
    "serial command control",
    "lab automation",
    "position feedback"
  ]
}

